-- Create enum type "enum_lesson_type"
CREATE TYPE "public"."enum_lesson_type" AS ENUM ('PRACTICE', 'THEORY');
-- Create "lessons" table
CREATE TABLE "public"."lessons" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "rup_name" text NOT NULL, "discipline_name" text NULL, "topic_name" text NULL, "teacher_id" uuid NOT NULL, "event_date" timestamptz NOT NULL, "group_id" uuid NOT NULL, "type" "public"."enum_lesson_type" NOT NULL, "goals" text NULL, "tasks" text NULL, "expected" text NULL, "internet_resources" uuid[] NULL, "technical_resources" uuid[] NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("id"), CONSTRAINT "fk_lesson_groups" FOREIGN KEY ("group_id") REFERENCES "public"."groups" ("keycloak_id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "fk_lesson_teacher" FOREIGN KEY ("teacher_id") REFERENCES "public"."users" ("keycloak_id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create "lesson_progress" table
CREATE TABLE "public"."lesson_progress" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "lesson_id" uuid NOT NULL, "name" text NOT NULL, "start_minute" integer[] NOT NULL, "end_minute" integer[] NOT NULL, "content" text[] NULL, PRIMARY KEY ("id"), CONSTRAINT "fk_lesson_progress_lesson" FOREIGN KEY ("lesson_id") REFERENCES "public"."lessons" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
